from duckduckgo_search import DDGS
import time

with DDGS() as ddgs:
    # Try maps search for medical tourism related places
    try:
        maps = list(ddgs.maps('medical tourism hospital China', place='China', max_results=5))
        print('Maps results:')
        for m in maps:
            print(f'  {m}')
    except Exception as e:
        print(f'Maps error: {e}')

    time.sleep(2)

    # Try images
    try:
        imgs = list(ddgs.images('medical tourism China hospital', region='wt-wt', max_results=3))
        print('Images:')
        for i in imgs:
            print(f'  {i[\"title\"]} - {i[\"image\"]}')
    except Exception as e:
        print(f'Images error: {e}')
" 2>&1 | grep -v RuntimeWarning"}

